package hu.synostream.android;
import android.app.Dialog;import android.view.*;import android.widget.*;import java.nio.charset.StandardCharsets;
final class AboutUi {
 static void show(MainActivity a,String requested){String page=java.util.Set.of("about","legal","gpl","components").contains(requested)?requested:"about";Dialog dialog=a.screenDialog(),old=a.informationDialog;a.informationDialog=dialog;a.informationPage=page;if(old!=null)old.dismiss();LinearLayout root=a.column();String title=a.getString(page.equals("about")?R.string.about_title:page.equals("legal")?R.string.legal_title:page.equals("gpl")?R.string.full_gpl:R.string.components);root.addView(a.dialogBar(title,()->{if(page.equals("about"))dialog.dismiss();else show(a,page.equals("legal")?"about":"legal");}),a.lp(-1,52));ScrollView scroll=new ScrollView(a);scroll.setId(R.id.information_scroll);LinearLayout body=a.column();body.setPadding(a.dp(20),a.dp(16),a.dp(20),a.dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 if(page.equals("about")){ImageView icon=new ImageView(a);icon.setImageResource(R.drawable.synostream_icon);icon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);body.addView(icon,a.lp(72,72));body.addView(a.text("SynoStream Android",24,MainActivity.TEXT));body.addView(a.text(a.getString(R.string.about_version,BuildConfig.VERSION_NAME),17,MainActivity.PURPLE));body.addView(a.text(a.getString(R.string.about_release),14,MainActivity.MUTED));body.addView(a.text(a.getString(R.string.about_copyright),15,MainActivity.TEXT));body.addView(a.text(a.getString(R.string.about_license),15,MainActivity.TEXT));TextView summary=a.text(a.getString(R.string.about_legal_summary),15,MainActivity.MUTED);summary.setPadding(0,a.dp(16),0,a.dp(12));body.addView(summary);body.addView(a.button(a.getString(R.string.about_legal_button),()->show(a,"legal")),a.lp(-1,64));body.addView(a.text(a.getString(R.string.about_description),15,MainActivity.MUTED));}
 else if(page.equals("legal")){body.addView(a.text(a.getString(R.string.legal_notice),15,MainActivity.TEXT));body.addView(a.button(a.getString(R.string.full_gpl),()->show(a,"gpl")),a.lp(-1,60));body.addView(a.button(a.getString(R.string.components),()->show(a,"components")),a.lp(-1,60));}
 else{TextView text=a.text(asset(a,page.equals("gpl")?"LICENSE.txt":"en".equals(UiLocale.language(a))?"NOTICE.en.txt":"NOTICE.hu.txt"),14,MainActivity.TEXT);text.setId(R.id.legal_text);text.setTextIsSelectable(true);body.addView(text);}
 dialog.setOnCancelListener(d->{if(!page.equals("about")&&!a.isChangingConfigurations())a.s.main.post(()->{if(!a.isDestroyed())show(a,page.equals("legal")?"about":"legal");});});dialog.setOnDismissListener(d->{if(a.informationDialog==dialog){a.informationDialog=null;a.informationPage="";}});a.showScreen(dialog,root);}
 static String asset(MainActivity a,String name){try(java.io.InputStream in=a.getAssets().open(name)){return new String(NasClient.readBounded(in,512*1024),StandardCharsets.UTF_8);}catch(Exception unavailable){return a.getString(R.string.legal_unavailable);}}
 private AboutUi(){}
}
